/** Best-effort human-readable message from a Connect error JSON body. */
function connectErrorMessage(bodyText) {
    const parsed = safeJsonParse(bodyText);
    if (isRecord(parsed) && typeof parsed.message === "string" && parsed.message !== "") {
        return parsed.message;
    }
    return bodyText.slice(0, 300) || "(empty response body)";
}
const MAX_GITHUB_TOKEN_RETRY_AFTER_MS = 60 * 60_000;
